ALTER TABLE categories ADD COLUMN note TEXT NOT NULL DEFAULT '';

DELETE FROM category_aliases;
DELETE FROM categories;

INSERT INTO categories (name, note, sort_order) VALUES
  ('Raw Material', 'Material that becomes part of the manufactured brass product.', 10),
  ('Tools', 'Tools, fixtures and gauges used for drilling, holding, cutting or checking products.', 20),
  ('Supplies', 'Items that are regularly consumed during production, cleaning or machine operation.', 30),
  ('Machines', 'New machines, equipment and major machine upgrades.', 40),
  ('Repairs', 'Machine repairs, replacement parts, servicing and factory maintenance work.', 50),
  ('Wages', 'Payments made directly to workers, operators, helpers or temporary labour.', 60),
  ('Outside Work', 'Production or processing work completed by another workshop or outside party.', 70),
  ('Power & Fuel', 'Electricity and fuel used to operate factory machines and equipment.', 80),
  ('Transport', 'Costs for moving materials, products, machines or other factory goods.', 90),
  ('Packing', 'Materials and costs used for packing and dispatching finished products.', 100),
  ('Factory Expense', 'General factory, premises, safety and worker-welfare expenses.', 110),
  ('Office Expense', 'Office, administration, banking, software and professional-service expenses.', 120),
  ('Tax & Fees', 'Taxes, licences, statutory charges and government payments.', 130),
  ('Advance', 'Money paid before receiving the final bill, material, service or settlement.', 140);

